        if (dir === 'down') { b.vl(cx - 1, ty + 1, th - 1, '#3a4670'); b.p(cx, ty + 2, '#e8d8a8'); b.p(cx, ty + 4, '#e8d8a8'); b.hl(tx, ty, tw, '#6a7aa8'); }
