        for (let i = 0; i < Math.max(1, tw >> 2); i++) if (r() < 0.7) { const ax = 5 + ((r() * (W - 12)) | 0), ay = 4 + ((r() * Math.max(1, rh - 10)) | 0); if (ay + 4 < rh - 2) dish(b, ax, ay); }
