        // голуби на парапеті
        if (r() < 0.5) { const gx = 6 + ((r() * (W - 14)) | 0); b.rect(gx, rh - 3, 2, 1, '#8a8ca4'); b.p(gx + 1, rh - 4, '#6a6c84'); b.rect(gx + 4, rh - 3, 2, 1, '#9a9cb4'); }
