    for (let x = 0; x < W; x += 16) { b.rect(x + 5, H - 4, 3, 2, '#2a2530'); b.p(x + 5, H - 4, '#4a4452'); } // продухи підвалу
    for (const d of doors) entranceAt(b, d * 16, fy, H, seed + d, R);
