    b.vl(0, fy, H - fy, '#e8eef4'); b.vl(W - 1, fy, H - fy, '#2a3448');
    // перший поверх (лобі), вхід
    b.rect(0, bottom, W, 10, '#5a6272'); b.hl(0, bottom, W, '#aab4c4'); b.hl(0, bottom + 1, W, SHADE, 0.4);
    for (let x = 3; x < W - 3; x += 8) { b.rect(x, bottom + 3, 6, 6, '#ffe2a0'); b.hl(x, bottom + 3, 6, '#fff4d0'); b.vl(x + 5, bottom + 3, 6, '#d8a868'); }
    const doors = doorList(o, tw, [tw >> 1]);
    for (const d of doors) {
      const dx = d * 16;
      b.rect(dx - 1, bottom - 2, 18, 2, '#2a3448'); b.hl(dx - 1, bottom - 2, 18, '#c8d0dc'); shadeRect(b, dx, bottom, 17, 2, 0.45);
      b.rect(dx + 2, bottom + 1, 12, 9, '#2a3a54'); b.rect(dx + 3, bottom + 2, 4, 8, '#9fd0ec'); b.rect(dx + 9, bottom + 2, 4, 8, '#9fd0ec');
      b.vl(dx + 3, bottom + 2, 8, '#e8f6ff'); b.vl(dx + 9, bottom + 2, 8, '#e8f6ff'); b.vl(dx + 8, bottom + 1, 9, '#c8d4e0');
    }
    // вивіска-лайтбокс
