    coffee: { sign: 'КАВА', bg: '#5a3426', fg: '#f7d8a8', stripe: '#c8844a', awn: ['#8a4a2a', '#f4e4c8'], wall: '#d8c0a0', goods: ['#f4ede4', '#8b5a3a', '#c8844a', '#e8c890'] },
