    const S = SHOPS[o.type] || (o.color ? { sign: '', bg: o.color, fg: '#fff4d6', stripe: lt(o.color, 0.4), awn: [o.color, '#f4ece0'], wall: '#e4d8c4', goods: ['#f7c948', '#d8443a', '#7ab84e', '#f4ede4'] } : SHOPS.coffee);
