        if (!b.a(x, y + 3) || !b.a(x, y - 1)) continue;
        b.p(x, y - 1, '#fff8ea'); b.p(x, y, '#fff2dc'); b.p(x - 1, y + 1, '#f4e4d0'); b.p(x, y + 1, '#ffffff'); b.p(x + 1, y + 1, '#e8c4c4');
        b.p(x - 1, y + 2, '#e8d4c4'); b.p(x, y + 2, '#f6e6da'); b.p(x + 1, y + 2, '#c89aa4'); b.p(x, y + 3, pal[1]);
