        b.rect(2, 2, 8, 10, '#5a6a72'); b.vl(2, 2, 10, '#8a9aa2'); b.vl(9, 2, 10, '#3a4650'); for (let y = 4; y < 11; y += 2) b.hl(3, y, 6, '#4a5862');
        b.hl(1, 1, 10, '#c8a050'); b.hl(1, 2, 10, '#8a6a30'); b.ell(6, 1, 3.5, 0.8, '#1a1418');
        b.p(4, 0, '#e8e0d0'); b.p(7, 0, '#d8443a');
