        const KS = [['КАВА', '#8a4a2a', ['#f4ede4', '#8b5a3a', '#c8844a']], ['ПРЕСА', '#3c6fb4', ['#f4ede4', '#d8443a', '#f7c948']], ['КВІТИ', '#c85a8a', ['#ff7a9a', '#f7c948', '#fff2f0']], ['ШАУРМА', '#e0602a', ['#e8c890', '#7ab84e', '#d8443a']]];
        const ki = { coffee: 0, cafe: 0, press: 1, flowers: 2, shawarma: 3 }[o.type];
