        if (lineWidth(signs[0], false) <= 24) textInto(b, signs[0], 16, 17, '#fff8e0', false, 'center'); else tinyInto(b, signs[0], 16 - (tinyW(signs[0]) >> 1), 18, '#fff8e0');
        // віконце продажу: тепле світло, товар
