        for (let x = 6; x < 26; x += 3) { const gc = signs[2][(x / 3 | 0) % 3]; b.rect(x, 27, 2, 2, gc); b.p(x, 27, lt(gc, 0.4)); }
        b.hl(4, 25, 24, SHADE, 0.4); b.hl(3, 30, 26, R[4]);
