    b.blit(ch, 0, 0);
    if (F.fg) F.fg(b);
    // рамка
    b.rect(0, 0, 48, 1, P.ink); b.rect(0, 47, 48, 1, P.ink); b.rect(0, 0, 1, 48, P.ink); b.rect(47, 0, 1, 48, P.ink);
    b.hl(1, 1, 46, lt(bg, 0.35)); b.vl(1, 1, 46, lt(bg, 0.2));
