    if (mode === 'side') { b.ell(38, 16, 8, 2.5, cd); b.hl(32, 15, 10, dk(col, 0.45)); }
    else if (mode !== 'back') { b.ell(24, 18, 15, 3, dk(col, 0.45)); b.hl(12, 17, 24, cd); }
