  function scarfP(b, col, d1, d2, backLayer) {
    const cd = dk(col, 0.25);
    const pc = (x, y, c) => { const v = hash(x >> 1, y >> 1, 21); b.p(x, y, v < 0.1 ? d1 : v > 0.92 ? d2 : c); };
    if (backLayer) { for (let y = 4; y < 44; y++) for (let x = 6; x < 42; x++) { const dx = (x - 24) / 18, dy = (y - 22) / 19; if (dx * dx + dy * dy <= 1) pc(x, y, dx > 0.4 ? cd : col); } return; }
    // верх хустки над чолом і по боках обличчя
    for (let y = 2; y < 44; y++) for (let x = 4; x < 44; x++) {
      const dx = (x - 24) / 17, dy = (y - 22) / 19, fdx = (x + 0.5 - 24) / 11, fdy = (y + 0.5 - 25) / 12.5;
      if (dx * dx + dy * dy > 1) continue;
      if (fdx * fdx + fdy * fdy <= 1 && y > 13) continue;
      if (y > 36 && Math.abs(x - 24) > 8) continue;
      pc(x, y, dx > 0.4 || y > 34 ? cd : col);
    }
    b.ell(24, 40, 4, 3, cd); b.ell(19, 44, 3, 2, col); b.ell(29, 44, 3, 2, col);
  }
  function wreathP(b) {
    const L = '#4e8a3a', LL = '#7ab84e', fl = [P.red, P.yellow, '#5a8ae0', P.pink, P.white, P.orange];
    for (let a = Math.PI * 1.05; a <= Math.PI * 1.95; a += 0.06) { const x = 24 + Math.cos(a) * 15, y = 14 + Math.sin(a) * 8; b.ell(x, y, 2, 1.5, hash(Math.round(x), Math.round(y), 2) < 0.5 ? L : LL); }
    let k = 0;
    for (let a = Math.PI * 1.08; a <= Math.PI * 1.95; a += 0.16, k++) { const x = 24 + Math.cos(a) * 15, y = 13 + Math.sin(a) * 8; const c = fl[k % fl.length]; b.ell(x, y, 2.2, 2.2, c); b.p(Math.round(x), Math.round(y), k % fl.length === 1 ? P.orange : P.yellow); }
    const rib = ['#d8443a', '#f7c948', '#3c6fb4', '#7ab84e'];
    for (let i = 0; i < 4; i++) b.line(8 + i, 15, 5 + i * 2, 40, rib[i]);
  }
  function genPortrait(o) {
    const kind = o.type || 'player', v = o.variant;
    const set = PORTRAITS[kind] || PORTRAITS.player;
    const F = set[v] || (kind === 'player' ? set.office : kind === 'tck' ? set.polite : set.granny);
    return portraitBuf(F);
  }

  // ═══════════════════════════════ ФОНИ КАТ-СЦЕН 480×270 ═══════════════════════════════
  // вертикальний градієнт з дизерингом за списком кольорів
  function vgrad(b, x0, y0, w, h, cols) {
    for (let y = y0; y < y0 + h; y++) {
      const t = (y - y0) / Math.max(1, h - 1) * (cols.length - 1);
      const i = Math.min(cols.length - 2, Math.floor(t)), f = t - i;
      for (let x = x0; x < x0 + w; x++) b.p(x, y, f > bayer(x, y) ? cols[i + 1] : cols[i]);
    }
  }
  function quad(b, pts, col) { polyFill(b, pts, col); }
