    b.ell(240, 20, 26, 6, '#fff0b0'); b.ell(240, 20, 20, 4, '#fffadc'); b.ell(240, 26, 60, 10, '#fff0b0', 0.12);
    quad(b, [[0, 0], [150, 44], [150, 226], [0, 270]], '#3a3e38');
