    for (let y = py + 2; y < py + 6; y += 2) b.hl(13, y, 15, PLATE_S);
    b.vl(28, py, 15, PLATE_S); b.hl(12, py, 17, PLATE_L);
    b.rect(11, py + 6, 1, 9, PLATE_S); b.rect(29, py + 6, 1, 9, PLATE_S);
    // підсумки під магазини
    for (const x of [13, 18, 23]) { b.rect(x, py + 8, 4, 6, PLATE_S); b.hl(x, py + 8, 4, PLATE_L); b.p(x + 1, py + 9, PLATE); }
    // шеврон-прапор
    b.hl(23, py + 2, 4, '#3c6fd0'); b.hl(23, py + 3, 4, '#f0d030');
    // пояс
