    b.rect(10, 42 + oy, 3, 4, '#4e4c34'); b.rect(28, 42 + oy, 3, 4, '#4e4c34'); b.p(29, 43 + oy, '#c83a3a');
    // шия
    b.rect(17, 22 + oy, 7, 4, skinS);

    // ── руки й зброя
    const sleeve = (x0, y0, x1, y1, w, col) => {
      const n = Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0)) * 2 + 1;
      for (let i = 0; i <= n; i++) { const t = i / n, x = Math.round(x0 + (x1 - x0) * t), y = Math.round(y0 + (y1 - y0) * t); b.rect(x - (w >> 1), y - (w >> 1), w, w, col); }
    };
    const hand = (x, y) => { b.rect(x, y, 3, 3, skin); b.p(x + 2, y + 2, skinS); b.hl(x, y + 2, 3, skinS); b.p(x, y, lt(skin, 0.2)); };
    if (pose === 'rifle') {
      sleeve(10, 28, 9, 35, 4, CAMO); sleeve(9, 35, 15, 38, 3, CAMO);
      sleeve(31, 28, 32, 36, 4, JCAMO_S); sleeve(31, 37, 27, 42, 3, JCAMO_S);
      // автомат: приклад біля правого плеча (екранно ліворуч), ствол униз праворуч
      const A = [6, 31], B = [38, 50];
      const n = 90;
      for (let i = 0; i <= n; i++) {
        const t = i / n, x = Math.round(A[0] + (B[0] - A[0]) * t), y = Math.round(A[1] + (B[1] - A[1]) * t);
        let th = 0, c = GUN, cl = GUN_L;
        if (t < 0.2) th = 3; else if (t < 0.52) th = 4; else if (t < 0.78) { th = 3; c = GUN_W; cl = GUN_WL; } else if (t < 0.96) th = 1; else th = 2;
        for (let k = 0; k < th; k++) b.p(x, y + k, k === 0 ? cl : c);
      }
      // магазин (вигнутий) і пістолетне руків'я
      polyFill(b, [[20, 41], [24, 41], [22, 48], [18, 47]], '#3e3430'); b.line(20, 41, 18, 46, '#5a4c44');
      b.rect(15, 39, 2, 3, GUN);
      hand(14, 37); hand(26, 41);
    } else if (pose === 'crossed') {
      sleeve(10, 28, 10, 34, 4, CAMO); sleeve(31, 28, 31, 34, 4, JCAMO_S);
      sleeve(11, 35, 28, 35, 3, CAMO); sleeve(29, 33, 13, 33, 3, mix(CAMO, JCAMO_S, 0.5));
      hand(27, 33); hand(11, 31);
      // ремінь автомата і ствол над плечем
      b.line(14, 26, 27, 41, '#2e2a22');
      b.rect(31, 13, 2, 13, GUN); b.vl(31, 13, 13, GUN_L); b.rect(30, 12, 3, 2, GUN);
    } else {
      // сидить, кружка в обох руках
      sleeve(10, 28 + oy, 11, 36 + oy, 4, CAMO); sleeve(31, 28 + oy, 30, 36 + oy, 4, JCAMO_S);
      sleeve(12, 37 + oy, 17, 39 + oy, 3, CAMO); sleeve(29, 37 + oy, 23, 39 + oy, 3, JCAMO_S);
      b.rect(18, 36 + oy, 5, 5, '#5a7a8a'); b.hl(18, 36 + oy, 5, '#8aaab8'); b.vl(22, 37 + oy, 4, '#3a5868');
      hand(15, 37 + oy); hand(22, 37 + oy);
    }

    // ── голова
