    const bearded = hero || kind !== 'grunt' || true;
    const beardC = hero ? (hairStyle === 'none' || hairStyle === 'bald' ? '#6a5a50' : hair) : GR.beard;
    if (bearded) for (let y = fy + 3; y <= fy + 7; y++) for (let x = fcx - 6; x <= fcx + 6; x++) {
      if (!b.a(x, y)) continue;
      const dx = (x + 0.5 - fcx) / 6.5, dy = (y + 0.5 - fy) / 7;
      if (dx * dx + dy * dy > 1) continue;
      if (y === fy + 3 && Math.abs(x + 0.5 - fcx) < 3) continue;
      const h = hash(x, y, 17);
      if (h < (hero ? 0.55 : 0.8)) b.p(x, y, mix(skin, beardC, hero ? 0.32 : 0.55));
    }
    // волосся з-під шолома (бакенбарди)
