    for (const x of [18, 30, 62, 78, 92]) { b.vl(x, 19, 4, '#3a3630'); b.vl(x + 2, 19, 4, '#3a3630'); b.hl(x, 23, 3, '#2a2622'); b.p(x + 1, 22, '#5a564e'); } // петлі-поручні
    // нижня панель стіни: заклепки, потертості
    for (let x = 4; x < 106; x += 9) b.p(x, 53, '#8a8270');
    for (let k = 0; k < 14; k++) b.hl(4 + ((hash(k, 1, 7) * 98) | 0), 52 + ((hash(k, 2, 7) * 8) | 0), 2 + ((hash(k, 3, 7) * 3) | 0), VANI.wallD);
    // наліпка "МАСКУ НЕ ЗНІМАТИ"-стиль: тут — бортовий номер/табличка
    b.rect(86, 51, 12, 8, '#d8d2c4'); b.hl(86, 51, 12, '#f0ece2'); b.vl(97, 52, 7, '#a8a294'); b.rect(91, 52, 2, 6, '#c8302f'); b.rect(89, 54, 6, 2, '#c8302f'); b.hl(88, 59, 8, '#3a3630');
    // лавка
