    for (let x = 14; x < 106; x += 24) b.vl(x, 61, 3, VANI.seatD);
    b.rect(3, 65, 104, 7, '#2a2b26'); b.hl(3, 65, 104, '#44463c'); b.vl(3, 65, 7, '#3a3c34'); b.vl(106, 65, 7, '#1e1f1a');
    for (const x of [8, 56, 100]) b.rect(x, 66, 2, 6, '#4a4c44');
    // підлога (рифлений гумовий килимок)
    let y = 72, step = 2;
    b.rect(0, 72, 160, 18, '#24221e');
    while (y < 90) { b.hl(0, y, 160, '#302d28'); y += step; step = Math.min(5, step + 0.5) ; y = Math.round(y); }
    b.hl(0, 72, 160, '#151412');
    for (let x = 0; x < 108; x++) b.p(x, 72, '#0e0d0c');
    // термос на підлозі біля лавки
    b.rect(94, 63, 5, 9, '#3e6a44'); b.vl(94, 63, 9, '#5a8a5c'); b.vl(98, 63, 9, '#2a4a30'); b.rect(94, 61, 5, 2, '#c8c4b8'); b.hl(94, 61, 5, '#e8e4d8'); b.rect(95, 60, 3, 1, '#2a2826');
    // повістки на лавці
    b.rect(84, 59, 9, 2, '#f0ece2'); b.hl(85, 58, 7, '#e2dccf'); b.p(88, 58, '#c83a3a');
    // дверний проріз (прозорий) + рама
    b.rect(108, 14, 52, 58, VANI.seal);
    for (let yy = 16; yy < 72; yy++) for (let x = 110; x < 157; x++) b.clear(x, yy);
    b.vl(109, 15, 57, '#3a3630'); b.rect(157, 14, 3, 58, VANI.rib); b.vl(157, 14, 58, lt(VANI.rib, 0.2));
    b.hl(110, 15, 47, '#2e2b26');
