    // тротуар і бордюр
    b.rect(0, 40, 47, 16, '#c8bcae'); for (let y = 42; y < 56; y += 4) b.hl(0, y, 47, '#b4a898'); for (let x = 0; x < 47; x += 8) b.vl(x + ((x >> 3) & 1) * 4, 40, 16, '#b4a898');
    b.hl(0, 40, 47, '#e8e0d4');
    // загальний засвіт (ранок)
    for (let y = 0; y < 56; y++) for (let x = 0; x < 47; x++) b.p(x, y, '#fff6e0', 0.18);
