    b.rect(4, H - 2, W - 4, 2, SHADE, 0.3);
    const big = (src, x, y, col, dcol) => { // ×2 з глибиною 2 px
      for (let j = 0; j < src.h; j++) for (let i = 0; i < src.w; i++) if (src.a(i, j)) { b.rect(x + i * 2 + 2, y + j * 2 + 2, 2, 2, dcol); }
      for (let j = 0; j < src.h; j++) for (let i = 0; i < src.w; i++) if (src.a(i, j)) { b.rect(x + i * 2, y + j * 2, 2, 2, col); }
    };
