      if (Math.hypot(x - fx, y - fy - 2) < 3) c = cream;
      if (y > fy + 5 && y < fy + 8 && x > fx - 7 && x < fx + 8) c = red;
      if (Math.abs(x - (fx + 7) + (y - fy) * 0.3) < 1 && y < fy + 8 && y > fy - 6) c = ochre;
      if (v > 0.62 && Math.abs(Math.sin(x * 0.5)) < 0.3 && v < 0.75) c = cream; // колосся
      // птахи
      if (Math.abs(y - 4 - Math.abs(x - mw * 0.5) * 0.4) < 0.7 && Math.abs(x - mw * 0.5) < 4) c = cream;
