    const shadeTi = (u, extra) => { const v = u + (extra || 0); return v < 0.12 ? TI[0] : v < 0.32 ? TI[1] : v < 0.58 ? TI[2] : v < 0.8 ? TI[3] : v < 0.94 ? TI[4] : TI[5]; };
    const cx = 60;
