      const flare = t > 0.8 ? (t - 0.8) * 20 : 0;
      const hwL = t < 0.25 ? 7 + t * 10 : 9.5 + (t - 0.25) * 15 + flare, hwR = t < 0.25 ? 7 + t * 10 : 9.5 + (t - 0.25) * 12 + flare * 0.8;
      const x0 = Math.round(cx - 1 - hwL), x1 = Math.round(cx + hwR);
