    // пояс
    b.hl(cx - 9, sTop + 18, 19, TI[3]); b.hl(cx - 8, sTop + 19, 17, TI[1]);
    // плечі
    for (let y = 46 + oy; y < 54 + oy; y++) { const hw = y < 48 + oy ? 6 + (y - 46 - oy) * 2 : 10; for (let x = cx - hw - 1; x <= cx + hw; x++) b.p(x, y, shadeTi((x - (cx - hw - 1)) / (2 * hw + 1))); }
    // голова (обличчя повернуте вліво-вперед), волосся зібране
    b.ell(cx - 1, 39 + oy, 5, 6, TI[2]); b.ell(cx - 2, 38 + oy, 3.5, 4.5, TI[1]); b.p(cx - 4, 37 + oy, TI[0]); b.p(cx - 3, 36 + oy, TI[0]);
    b.ell(cx + 2, 34 + oy, 3.5, 3, TI[3]); b.p(cx + 1, 33 + oy, TI[2]);
    b.rect(cx - 2, 44 + oy, 4, 3, TI[2]); b.vl(cx + 1, 44 + oy, 3, TI[3]);
    b.p(cx - 3, 39 + oy, TI[4]); b.p(cx, 39 + oy, TI[4]); b.hl(cx - 2, 42 + oy, 2, TI[3]);
    // права рука (від глядача — праворуч) вгору з мечем
    const arm = (xa, ya, xb, yb, wdt) => { const n = Math.ceil(Math.hypot(xb - xa, yb - ya)); for (let i = 0; i <= n; i++) { const x = xa + (xb - xa) * i / n, y = ya + (yb - ya) * i / n; for (let k = -wdt; k <= wdt; k++) b.p(Math.round(x + k), Math.round(y), shadeTi((k + wdt) / (2 * wdt + 1), -0.05)); } };
    arm(cx + 8, 50 + oy, cx + 19, 26 + oy, 3); arm(cx + 19, 26 + oy, cx + 22, 18 + oy, 2);
    b.rect(cx + 19, 13 + oy, 6, 6, TI[2]); b.hl(cx + 19, 13 + oy, 6, TI[1]); b.vl(cx + 24, 14 + oy, 5, TI[4]); // кулак
    // меч: руків'я, хрестовина, довгий клинок
