    b.rect(cx + 15, 7 + oy, 14, 2, TI[3]); b.hl(cx + 15, 7 + oy, 14, TI[1]); b.p(cx + 15, 8 + oy, TI[2]);
    const bl = 7 + oy;
    for (let y = 0; y < bl; y++) { const x = cx + 20 + Math.round((bl - y) * 0.16); b.p(x, y, TI[0]); b.p(x + 1, y, y < 3 ? TI[1] : '#dfe6ee'); b.p(x + 2, y, TI[3]); if (y > 4) b.p(x + 3, y, TI[4]); }
    b.p(cx + 21 + Math.round(bl * 0.16), 0, '#ffffff');
    // ліва рука вбік-угору зі щитом
    arm(cx - 9, 50 + oy, cx - 21, 44 + oy, 3);
    const shx = cx - 30, shy = 46 + oy;
    b.ell(shx + 1, shy + 1, 14, 17, TI[4]);
    b.ell(shx, shy, 13.5, 16.5, (x, y, dx, dy) => { const l = -dx * 0.6 - dy * 0.55; return l > 0.5 ? TI[0] : l > 0.15 ? TI[1] : l > -0.25 ? TI[2] : l > -0.6 ? TI[3] : TI[4]; });
    for (let a = 0; a < Math.PI * 2; a += 0.05) { const x = shx + Math.cos(a) * 12, y = shy + Math.sin(a) * 15; b.p(Math.round(x), Math.round(y), Math.cos(a) + Math.sin(a) < 0 ? TI[0] : TI[3]); }
    const TRZ = ['#...#...#', '#...#...#', '#..###..#', '##.#.#.##', '.#######.', '....#....', '...###...', '....#....'];
    b.pat(shx - 3, shy - 5, TRZ, { '#': TI[4] }); b.pat(shx - 4, shy - 6, TRZ, { '#': TI[0] });
