    for (let x = 0; x < W; x += 2) b.p(x, 8, ((x >> 2) & 1) ? '#f0f0f0' : '#d8302a'); for (let x = 0; x < W; x += 2) b.p(x + 1, 8, ((x >> 2) & 1) ? '#f0f0f0' : '#d8302a');
    for (let x = 0; x < W; x += 32) { b.rect(x, 0, 2, H - 1, '#4a4a56'); b.vl(x, 0, H - 1, '#8a8a98'); }
    if (W >= 32) { const tx = W - 20; b.pat(tx, 11, ['....#....', '...#y#...', '...#y#...', '..#yky#..', '..#yky#..', '.#yyyyy#.', '.#yykyy#.', '#########'], { '#': '#d8302a', y: '#f7d23a', k: '#2a2228' }); }
    for (let k = 0; k < W / 10; k++) { const x = (hash(k, 1, 5) * W) | 0; b.p(x, 14 + ((hash(k, 2, 5) * 6) | 0), '#9a5a3a'); }
