      b.p(x, 0, C[4]); b.p(x, 1, C[3]);
      for (let y = 2; y <= 9; y++) b.p(x, y, y === 2 ? mix(col, '#ffffff', 0.15) : y === 9 ? C[1] : col);
      const st = (x >> 2) & 1 ? col : '#f4ece0';
      b.p(x, 10, mix(st, SUNL, 0.1)); b.p(x, 11, mix(st, SHADE, 0.2));
