        if (p.stand || p.kind === 'mstall') {
          for (const layer of p.kind === 'mstall' ? ['back', 'front'] : [undefined]) { const r = propSprite(p, layer); if (r) g.drawImage(r.img, r.dx, r.dy); }
        } else drawProp(g, p, p.x * T, p.y * T);
