    const gx = g % W, gy = (g / W) | 0;
    const hfn = (i) => { const dx = Math.abs(i % W - gx), dy = Math.abs(((i / W) | 0) - gy); return (dx + dy) + (1.4142 - 2) * Math.min(dx, dy); };
    gScore[s] = 0; seen[s] = searchId; cameFrom[s] = -1;
    hPush(s, hfn(s));
