        drawLight(ctx, b.x + b.w + 4, b.y + b.h + 8, sh, 'h');
        drawLight(ctx, b.x + b.w + 4, b.y - 2, sv, 'v');
        drawLight(ctx, b.x - 6, b.y + b.h + 8, sv, 'v');
