      for (const s of signs) {
        if (s.kind !== 'billboard' || s.x < x0 - 60 || s.x > x1 + 60 || s.y < y0 || s.y > y1 + 40) continue;
        drawBillboard(ctx, s);
      }
      // світло, кольорова градація, віньєт (35_lighting) — поверх світу, під бульбашки і HUD
