    coffee: { body: '#7a4b2c', hi: '#a46a40', lo: '#55321c', sign: '#2a1a14', fg: '#ffd890', t: 'КАВА' },
    shawarma: { body: '#d9a520', hi: '#efc54a', lo: '#a87a14', sign: '#b8322f', fg: '#fff2c0', t: 'ШАУРМА' },
    flowers: { body: '#3f8a3a', hi: '#62ad54', lo: '#2b6428', sign: '#f6eef2', fg: '#c03a6a', t: 'КВІТИ' },
    icecream: { body: '#e8e2d0', hi: '#fbf6ea', lo: '#bdb4a0', sign: '#4a8ad0', fg: '#ffffff', t: 'ПЛОМБІР' },
