    if (!burnt) { b.r(5, 6, 6, 3, '#a8a296'); b.hl(5, 6, 6, '#c8c2b6'); b.r(22, 6, 4, 2, '#7c776c'); } // вентиляція
    b.r(1, 11, 30, 22, K.body);
