      if (target < this.v) {
        const need = this.v - target;
        if (need > 40 && this.v > 50 && this.brakeCD <= 0 && this.isNearCam(260)) {
          sfx('brakes', { x: this.x, y: this.y, dur: 0.4 }); this.brakeCD = 2.5;
        }
        this.v = Math.max(target, this.v - EMERG * dt);
      } else this.v = Math.min(target, this.v + ACC * (1 - 0.45 * this.v / this.maxV) * dt); // розгін м'якшає ближче до крейсерської
      if (this.v < 0.5 && target < 0.5) this.v = 0;
      this.waitReason = this.v < 2 ? reason : null;

      // рух (жорстко без перекриттів)
      const r = moveHard(this, this.v * dt, dt);
      if (r.reverted) this.v = 0;
      if (r.entered) this.onEnterLane(r.entered);
