      this.dwellTotal = this.dwell;
      traffic.stats.stopArrivals++;
      this.arrivals = (this.arrivals || 0) + 1;
      // Round 12: поїздка коротка — через rideMax зупинок «Кінцева!», виходиш
      if (this.passenger && !this.wantExit) {
        this.rideStops = (this.rideStops || 0) + 1;
        if (this.rideStops >= (this.rideMax || 3)) {
          ui('toast', '«Кінцева! Виходимо!»', 1800);
          if (G.ui && G.ui.bubble) G.ui.bubble({ x: this.x, y: this.y - 14 }, 'Кінцева!', 1500, { style: 'shout' });
          this.wantExit = true;
        }
      }
      if (this.passenger && this.wantExit) exitRide(this);
