      this.len = DIM.len; this.hw = DIM.hw; this.vw = DIM.vw; this.half = DIM.len / 2; this.wid = DIM.hw;
      this.angle = angle || 0;
      this.hx = Math.cos(this.angle); this.hy = Math.sin(this.angle);
