      this.mode = opts.mode || 'patrol';
      this.modeT = 0;
      this.crew = opts.crew != null ? opts.crew : 4;
      this.crewTypes = opts.crewTypes || null;
      this.doorOpen = false;
      this.siren = false;
      this.braking = false;
      // рух смугами (G.traffic.nav)
