      this.plan = []; this.goal = null; this.stopAt = null; this.resC = null;
      this.parkL = null; this.parkS = null; this.parked = false; this.across = false; this.acrossDir = null;
      this.passing = null; this.jamT = 0; this.stillT = 0;
      this.notice = 0;
      this.sees = false;
      this.replanT = 0; this.blockCd = 0; this.blockT = 0;
      this.hornT = 1;
      this.dropQueue = 0; this.dropT = 0;
      this.dust = [];
