      if (this.ob) { const sg = Math.max(2, N.turningGap(this.ob.e)) + (this.ob.e.kind === 'bus' ? CFG.busGap : 0); lim(this.ob.gap < sg ? 0 : Math.sqrt(2 * BR * (this.ob.gap - sg))); } // запас: повернутий габарит у повороті більший
