    ctx.globalAlpha = a; ctx.fillStyle = '#24102c';
    const th = Math.max(2, w * 0.6); // товщина смуги на землі
    ctx.beginPath();
    ctx.moveTo(x - dir * w / 2, feet + 1); ctx.lineTo(x + L, feet + 1 - up);
    ctx.lineTo(x + L, feet + 1 - up - th * 0.6); ctx.lineTo(x - dir * w / 2, feet + 1 - th);
    ctx.closePath(); ctx.fill();
    if (cw) { ctx.beginPath(); ctx.ellipse(x + L * 0.82, feet - up * 0.82, cw * 0.9, Math.max(2, cw * 0.18), 0, 0, Math.PI * 2); ctx.fill(); }
