      if (T.text || !(zone in EXT_TARGET)) o.text = String(st.place || 'МАГАЗИН').toUpperCase();
      const fh = T.fh * 16 + 3;
      x.clearRect(T.x, EX.base - fh, tw, fh);
      const img = spr('prop', o);
