      if (st.village && tod.ph !== 'day') {
        const hx = 60, hy = EX.base - 76 + 2;
        for (const wx of [20, 50, 96]) for (let y = 43; y < 57; y++) for (let x = wx + 1; x < wx + 13; x++) { const i = (hy + y) * W + hx + x; if (base[i * 4 + 3]) kind[i] = tod.bo && wx !== 50 ? 0 : 1; }
      }
      const comps = components(W, H, kind.map((k) => (k === 1 ? 1 : 0)));
      const put = (i, r, g, b, a) => { o[i * 4] = r; o[i * 4 + 1] = g; o[i * 4 + 2] = b; o[i * 4 + 3] = Math.round(a * 255); };
