      const em = tod.em;
      const shop = !T.open && !st.village && !T.church && st.zone !== 'home' && st.zone !== 'office'; // магазини — з генератором
      comps.forEach((cp, ci) => {
        const cx = (cp.x0 + cp.x1) >> 1, cy = (cp.y0 + cp.y1) >> 1, tgt = inT(cx, cy);
        const big = cp.px.length > 60; // вивіски/вітрини — не "вікна"
        const rnd = hsh2(cp.x0, cp.y0, 11);
        if (tod.bo) {
          if (st.village) { for (const j of cp.px) put(j, base[j * 4], base[j * 4 + 1], base[j * 4 + 2], 0.9); return; }
          if (tgt && shop) { for (const j of cp.px) { put(j, base[j * 4], Math.round(base[j * 4 + 1] * 0.9), Math.round(base[j * 4 + 2] * 0.72), 0.85); wt[j] = 0.3; } return; } // генератор
          if (tgt && st.zone === 'office' && !big && rnd < 0.3) { for (const j of cp.px) { const y = (j / W) | 0, k = (y - cp.y0) / Math.max(1, cp.y1 - cp.y0); put(j, 110 + 30 * k, 140 + 30 * k, 230, 0.7); } return; } // монітори на ДБЖ
          if (big || rnd > 0.07) return;
          const pb = hsh2(cp.x0, cp.y0, 12) < 0.35; // павербанк (холодне) або свічка
          for (const j of cp.px) { const y = (j / W) | 0, k = (y - cp.y0) / Math.max(1, cp.y1 - cp.y0); put(j, pb ? 120 : 150, pb ? 140 : 76, pb ? 190 : 34, 0.45 + 0.4 * k); }
          return;
        }
        if (!tgt && !big && rnd > tod.keep) return;
        if (big) { for (const j of cp.px) { put(j, base[j * 4], Math.round(base[j * 4 + 1] * 0.92), Math.round(base[j * 4 + 2] * 0.76), em * 0.88); wt[j] = 0.3; } return; }
        for (const j of cp.px) put(j, base[j * 4], base[j * 4 + 1], base[j * 4 + 2], em);
      });
