  // офіс (round 7: колл-центр — ряд кабінок з моніторами й гарнітурами, табло черги дзвінків, плакат)
  function headset(b, x, y, col) { // гарнітура: дужка, навушники, мікрофон
    b.hl(x + 1, y, 6, col); b.p(x, y + 1, col); b.p(x + 7, y + 1, col);
    b.rect(x - 1, y + 2, 2, 3, col); b.rect(x + 7, y + 2, 2, 3, col); b.p(x - 1, y + 2, '#5a5a66');
    b.line(x, y + 5, x + 3, y + 6, col); b.p(x + 4, y + 6, '#d8443a');
  }
  function officeBack(late, tk) {
    tk = tk || 'day';
    const ph = tk.replace('B', ''), bo = tk.endsWith('B'), dk = ph === 'night' || ph === 'dusk';
    return ebuf('end_office_back' + (late ? 'L' : '') + tk, 160, 90, (b) => {
      ceiling(b, '#d8d4cc', '#b4b0a8', [20, 100]);
      b.rect(0, 10, 160, 52, '#e8e4dc'); b.rect(0, 50, 160, 12, '#d0ccc4'); b.hl(0, 50, 160, '#b8b4ac');
      // панорамне вікно
      b.rect(4, 12, 80, 38, '#c8c4bc');
      band(b, 6, 14, 76, 34, ph !== 'day' ? WINSKY[ph] : late ? ['#9ab0c8', '#b0c0d0', '#c8d0d8'] : ['#7ab4dc', '#9cc8e4', '#c4dcea', '#e8e0c8']);
      if (dk) for (let k = 0; k < 26; k++) b.p(7 + ((hh(k, 1, 62) * 74) | 0), 15 + ((hh(k, 2, 62) * 14) | 0), k % 3 ? '#8890c0' : '#ffffff');
      if (ph === 'night') { b.ell(70, 22, 3, 3, '#f4f0d8'); b.ell(69, 21, 1.5, 1.5, '#fffbe8'); }
      if (ph === 'eve') { b.ell(64, 40, 6, 6, '#fff0b0'); b.ell(64, 40, 9, 9, '#ffb060', 0.25); }
      if (ph === 'dawn') { b.ell(18, 42, 6, 6, '#fff0c0'); b.ell(18, 42, 9, 9, '#ffb080', 0.25); }
      const SKL = { day: ['#8a9cb8', '#a0acc4', '#b8c4d8', '#6a7c98', 0], dawn: ['#6a5a82', '#7a6890', '#8a7090', '#4a3e5a', 0.12], eve: ['#8a6074', '#9a6c7c', '#b07c84', '#6a4a58', 0.1],
        dusk: ['#2a2442', '#30284a', '#3a3054', '#1e1a30', 0.4], night: ['#12152a', '#161a32', '#1e2440', '#0c0e1c', 0.22] }[ph] || null;
      for (let x = 6; x < 82;) {
        const K = SKL || ['#8a9cb8', '#a0acc4', '#b8c4d8', '#6a7c98', 0];
        const w = 6 + ((hh(x, 1, 8) * 8) | 0), h = 8 + ((hh(x, 2, 8) * 20) | 0), col = hh(x, 3, 8) < 0.5 ? K[0] : K[1];
        b.rect(x, 48 - h, w, h, col); b.hl(x, 48 - h, w, K[2]);
        for (let y = 48 - h + 2; y < 47; y += 3) for (let i = x + 1; i < x + w - 1; i += 2) b.p(i, y, hh(i, y, 63) < (bo ? 0.03 : K[4]) ? (bo ? '#ff9a40' : '#ffc870') : K[3]);
        x += w + 1;
        if (x > 74) break;
      }
      const crC = dk ? '#3a3040' : '#d8a040';
      b.vl(60, 18, 12, crC); b.hl(54, 18, 18, crC); b.vl(70, 18, 3, crC); // кран
      if (dk) b.p(72, 18, '#ff4030');
      for (let x = 4; x <= 82; x += 20) b.rect(x, 12, 2, 38, '#c8c4bc');
      for (let y = 14; y < 20; y += 2) b.hl(6, y, 76, '#e0dcd4');
      // годинник (циферблат; стрілки — в анімації)
      b.ell(98, 19, 6, 6, '#3a3440'); b.ell(98, 19, 5, 5, '#ffffff'); for (let a = 0; a < 12; a += 3) b.p(Math.round(98 + Math.cos(a * Math.PI / 6) * 4), Math.round(19 + Math.sin(a * Math.PI / 6) * 4), '#8a8494');
      // плакат колл-центру
      b.rect(111, 12, 48, 22, '#c8302f'); b.rect(112, 13, 46, 20, '#d8443a');
      btext(b, 'ДЗВІНОК', 135, 13, '#ffffff', 'center'); btext(b, 'ВАЖЛИВИЙ', 135, 22, '#ffd23a', 'center');
      // табло черги дзвінків: слухавка + «47»
      const qc = late ? '#ff6a5a' : '#7aff9a';
      b.rect(116, 37, 24, 10, '#1a1e28'); b.hl(116, 37, 24, '#3a4050');
      b.rect(119, 40, 2, 4, qc); b.hl(119, 40, 5, qc); b.rect(123, 40, 2, 4, qc); // слухавка
      btext(b, '47', 133, 37, qc, 'center');
      // ряд кабінок: перегородки, монітори, гарнітури на перегородках
      for (let k = 0; k < 4; k++) {
        const x = 6 + k * 23;
        b.rect(x + 5, 42, 10, 7, '#2a2a30'); b.rect(x + 6, 43, 8, 5, k === 2 && late ? '#c8302f' : '#4a7ac8'); b.hl(x + 6, 43, 8, '#8ab0e8');
        b.rect(x, 49, 21, 13, '#7a86a0'); b.hl(x, 49, 21, '#a8b4cc'); b.vl(x + 20, 49, 13, '#5a6680'); b.vl(x, 49, 13, '#8a96b0');
        b.hl(x + 2, 55, 17, '#6a7690');
        headset(b, x + 2, 45, '#2a2a30');
      }
      // кулер
      b.rect(102, 42, 10, 20, '#e8ecf0'); b.hl(102, 42, 10, '#ffffff'); b.vl(111, 42, 20, '#c8ccd2'); b.rect(103, 32, 8, 10, '#8ac8f0'); b.hl(103, 32, 8, '#c8e8ff'); b.vl(103, 32, 10, '#b0e0ff'); b.rect(104, 30, 6, 2, '#5aa0d8');
      b.p(104, 47, '#3c6fb4'); b.p(109, 47, '#d8443a'); b.rect(104, 50, 6, 1, '#a8acb4');
      // рослина
      b.rect(145, 50, 10, 11, '#c8643a'); b.hl(145, 50, 10, '#e88a5a');
      for (let k = 0; k < 7; k++) b.line(150, 50, 143 + k * 2.4, 36 + (k & 1) * 4, k & 1 ? '#5e9846' : '#7ab84e');
      for (let y = 62; y < 90; y++) for (let x = 0; x < 160; x++) b.p(x, y, ((x >> 3) + (y >> 2)) & 1 ? '#8a90a0' : '#8288a0');
      b.hl(0, 62, 160, '#6a7080');
    });
  }
