    for (const b of p.say || []) { if (n <= 0) break; const L = bubLayout(b, X, Y); drawBubble(ctx, b, L, n); n -= b.t.length; }
    if (p.capB && n > 0) { const L = capLayout(p.capB, X, Y, w, h, true); drawCap(ctx, L, n); n -= p.capB.length; }
