    if (u.measure(text, 8) + timerW + 24 > Z.maxW && o.short) text = o.short;
    while (text.length > 4 && u.measure(text, 8) + timerW + 24 > Z.maxW) text = text.slice(0, -2) + '…';
    const tw = u.measure(text, 8) + timerW;
    const w = Math.round(tw + 24), h = 13, x = Math.round(Z.cx - w / 2);
