    if (age > 6.5) { S.phone = null; return; }
    const VH = G.cfg.VIEW_H;
    const slide = Math.min(1, age / 0.25, (6.5 - age) / 0.35);
    const shake = age < 2.6 && Math.floor(age * 6) % 3 !== 2 ? (Math.floor(G.realTime * 40) % 2 ? 1 : -1) : 0;
    const touch = !!(G.touch && G.touch.active); // сенсор: правіше від підказки стіка (38..90 × 178..230)
    const x0 = touch ? 96 : 4;
