    if (shake) { ctx.fillStyle = '#ff9080'; ctx.fillRect(x + 2, y + 9, 1, 3); ctx.fillRect(x + 19, y + 15, 1, 3); ctx.fillRect(x + 2, y + 17, 1, 3); ctx.fillRect(x + 19, y + 7, 1, 3); }
