      g.fillStyle = '#d42a2a'; g.fillRect(bx - 3, 9, 7, 2); g.fillRect(bx + 2, 10, 2, 4); g.fillStyle = '#9e1a22'; g.fillRect(bx - 3, 10, 7, 1);
