    g.fillStyle = '#6a4630'; g.fillRect(bx - 8, 11, 4, 1); g.fillRect(bx - 9, 10, 1, 1); g.fillRect(bx + 5, 12, 4, 1); g.fillRect(bx + 9, 11, 1, 1);
