    if (!S || S._winter || !S.drawBg) return false;
    const orig = S.drawBg;
    S.drawBg = function (ctx) { const r = orig.apply(this, arguments); try { WN.drawSnow(ctx, 0.5, { cam: false, bliz: 0 }); } catch (e) { /* */ } return r; };
